import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { Pie } from "@remotion/shapes";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type PieChartMacroProps = Record<string, any>;

const PieChartMacro: React.FC<PieChartMacroProps> = ({
  backgroundColor = "#0d0d0d",
  transparentBackground = false,
  durationInSeconds = 5,
  title = "MACRONUTRIENTES",
  textColor = "#ffffff",
  pieRadius = 360,
  items = [
    { label: "PROTEÍNA", percentage: 40, color: "#FF4B4B" },
    { label: "CARBOHIDRATOS", percentage: 30, color: "#4B90FF" },
    { label: "GRASAS SALUDABLES", percentage: 30, color: "#FFD14B" },
  ],
}) => {
  {/* Load Fonts */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  // Layout & Styling Parsers
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const strokeColor = transparentBackground ? "transparent" : backgroundColor;

  const total = items.reduce((acc, curr) => acc + curr.percentage, 0);

  // General Animations
  const titleOpacity = interpolate(frame, [5, 20], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const titleY = interpolate(
    spring({
      frame: frame - 5,
      fps,
      config: { damping: 14 },
    }),
    [0, 1],
    [30, 0]
  );

  const pieScale = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  // Sweeping Pie Chart Logic
  const startSweepFrame = 20;
  const sweepDuration = 70;

  const globalProgress = interpolate(
    frame,
    [startSweepFrame, startSweepFrame + sweepDuration],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );

  const slicesData = items.map((item, i) => {
    const sliceRatio = total === 0 ? 0 : item.percentage / total;
    const previousRatio = items
      .slice(0, i)
      .reduce((acc, curr) => acc + (total === 0 ? 0 : curr.percentage / total), 0);
    const endRatio = previousRatio + sliceRatio;

    let currentSliceProgress = 0;
    if (globalProgress > previousRatio) {
      if (globalProgress >= endRatio) {
        currentSliceProgress = sliceRatio;
      } else {
        currentSliceProgress = globalProgress - previousRatio;
      }
    }

    const rotation = previousRatio * Math.PI * 2;
    const currentPercentage =
      sliceRatio === 0 ? 0 : (currentSliceProgress / sliceRatio) * item.percentage;

    // Inverse cubic out mapping to approximate the exact start frame for individual slice legend animations
    const t = 1 - Math.cbrt(1 - previousRatio);
    const exactStartFrame = startSweepFrame + t * sweepDuration;

    return {
      ...item,
      sliceRatio,
      rotation,
      currentSliceProgress,
      currentPercentage,
      exactStartFrame,
    };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        color: textColor,
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
          paddingTop: height * 0.15,
          paddingBottom: height * 0.1,
          boxSizing: "border-box",
        }}
      >
        {/* Title */}
        <div
          style={{
            fontSize: "64px",
            fontWeight: 800,
            letterSpacing: "4px",
            marginBottom: "100px",
            textTransform: "uppercase",
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            textAlign: "center",
            transition: "none",
          }}
        >
          {title}
        </div>

        {/* Pie Chart Wrapper */}
        <div
          style={{
            position: "relative",
            width: pieRadius * 2,
            height: pieRadius * 2,
            transform: `scale(${pieScale})`,
            marginBottom: "120px",
            transition: "none",
          }}
        >
          {slicesData.map((data, i) => (
            <div
              key={i}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                transition: "none",
              }}
            >
              <Pie
                radius={pieRadius}
                progress={data.currentSliceProgress}
                rotation={data.rotation}
                fill={data.color}
                stroke={strokeColor}
                strokeWidth={6}
              />
            </div>
          ))}
        </div>

        {/* Legend Flex Stack */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "36px",
            width: "85%",
            maxWidth: "900px",
          }}
        >
          {slicesData.map((data, i) => {
            const legendSpring = spring({
              frame: frame - data.exactStartFrame,
              fps,
              config: { damping: 14, stiffness: 90 },
            });

            const opacity = interpolate(
              frame - data.exactStartFrame,
              [0, 10],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            const yOffset = interpolate(legendSpring, [0, 1], [40, 0]);

            // Lock final frame to user input precisely, else round for counting effect
            const displayValue =
              data.currentSliceProgress >= data.sliceRatio
                ? data.percentage
                : Math.round(data.currentPercentage);

            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  width: "100%",
                  opacity,
                  transform: `translateY(${yOffset}px)`,
                  transition: "none",
                }}
              >
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "24px",
                  }}
                >
                  <div
                    style={{
                      width: "48px",
                      height: "48px",
                      backgroundColor: data.color,
                      borderRadius: "12px",
                      boxShadow: `0 4px 12px ${data.color}40`,
                    }}
                  />
                  <span style={{ fontSize: "42px", fontWeight: 700 }}>
                    {data.label}
                  </span>
                </div>
                <span
                  style={{
                    fontSize: "56px",
                    fontWeight: 800,
                    fontFamily: "Inter",
                  }}
                >
                  {displayValue}%
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PieChartMacro;